-- ====================================================================
-- StudyFlow: Supabase Row Level Security (RLS) Policies
-- File: server/config/supabase_subjects_policies.sql
-- 
-- Target Table Schema:
--   Table Name: public."Subjects" (or public.subjects)
--   Columns:
--     - id           : BIGINT (Primary Key, Identity generated by default)
--     - created_at   : TIMESTAMPTZ (DEFAULT now())
--     - user_id      : UUID NOT NULL (References auth.users(id) ON DELETE CASCADE)
--     - subject_name : TEXT NOT NULL
--     - subject_code : TEXT NULL
--     - progress     : NUMERIC / INTEGER DEFAULT 0
-- ====================================================================
-- INSTRUCTIONS TO RUN:
-- 1. Open the Supabase Dashboard: https://supabase.com/dashboard/project/_/sql
-- 2. Select your StudyFlow project.
-- 3. Click on the "SQL Editor" icon in the left navigation sidebar.
-- 4. Click "+ New query".
-- 5. Copy and paste the entire script below into the editor.
-- 6. Click "Run" (or press Ctrl + Enter / Cmd + Enter).
-- 7. Verify the success message: "Success. No rows returned".
-- ====================================================================

-- ─── 1. APPLY POLICIES FOR CASE-SENSITIVE public."Subjects" ─────────
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_tables 
    WHERE schemaname = 'public' AND tablename = 'Subjects'
  ) THEN
    -- Enable Row Level Security
    EXECUTE 'ALTER TABLE public."Subjects" ENABLE ROW LEVEL SECURITY;';

    -- SELECT Policy: Authenticated users can only read their own subjects
    EXECUTE 'DROP POLICY IF EXISTS "Users can read their own subjects" ON public."Subjects";';
    EXECUTE 'CREATE POLICY "Users can read their own subjects"
      ON public."Subjects"
      FOR SELECT
      TO authenticated
      USING (auth.uid() = user_id);';

    -- INSERT Policy: Authenticated users can only insert subjects belonging to their own user_id
    EXECUTE 'DROP POLICY IF EXISTS "Users can insert their own subjects" ON public."Subjects";';
    EXECUTE 'CREATE POLICY "Users can insert their own subjects"
      ON public."Subjects"
      FOR INSERT
      TO authenticated
      WITH CHECK (auth.uid() = user_id);';

    -- UPDATE Policy: Authenticated users can only update their own subjects
    EXECUTE 'DROP POLICY IF EXISTS "Users can update their own subjects" ON public."Subjects";';
    EXECUTE 'CREATE POLICY "Users can update their own subjects"
      ON public."Subjects"
      FOR UPDATE
      TO authenticated
      USING (auth.uid() = user_id)
      WITH CHECK (auth.uid() = user_id);';

    -- DELETE Policy: Authenticated users can only delete their own subjects
    EXECUTE 'DROP POLICY IF EXISTS "Users can delete their own subjects" ON public."Subjects";';
    EXECUTE 'CREATE POLICY "Users can delete their own subjects"
      ON public."Subjects"
      FOR DELETE
      TO authenticated
      USING (auth.uid() = user_id);';

    RAISE NOTICE 'RLS policies successfully applied to public."Subjects".';
  END IF;
END $$;

-- ─── 2. APPLY POLICIES FOR LOWERCASE public.subjects (IF PRESENT) ───
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_tables 
    WHERE schemaname = 'public' AND tablename = 'subjects'
  ) THEN
    -- Enable Row Level Security
    EXECUTE 'ALTER TABLE public.subjects ENABLE ROW LEVEL SECURITY;';

    -- SELECT Policy
    EXECUTE 'DROP POLICY IF EXISTS "Users can read their own subjects" ON public.subjects;';
    EXECUTE 'CREATE POLICY "Users can read their own subjects"
      ON public.subjects
      FOR SELECT
      TO authenticated
      USING (auth.uid() = user_id);';

    -- INSERT Policy
    EXECUTE 'DROP POLICY IF EXISTS "Users can insert their own subjects" ON public.subjects;';
    EXECUTE 'CREATE POLICY "Users can insert their own subjects"
      ON public.subjects
      FOR INSERT
      TO authenticated
      WITH CHECK (auth.uid() = user_id);';

    -- UPDATE Policy
    EXECUTE 'DROP POLICY IF EXISTS "Users can update their own subjects" ON public.subjects;';
    EXECUTE 'CREATE POLICY "Users can update their own subjects"
      ON public.subjects
      FOR UPDATE
      TO authenticated
      USING (auth.uid() = user_id)
      WITH CHECK (auth.uid() = user_id);';

    -- DELETE Policy
    EXECUTE 'DROP POLICY IF EXISTS "Users can delete their own subjects" ON public.subjects;';
    EXECUTE 'CREATE POLICY "Users can delete their own subjects"
      ON public.subjects
      FOR DELETE
      TO authenticated
      USING (auth.uid() = user_id);';

    RAISE NOTICE 'RLS policies successfully applied to public.subjects.';
  END IF;
END $$;

